def f(g):
    objs=objects(g)
    # group by column, find vertical pairs, min gap, return bottom
    from collections import defaultdict
    bycol=defaultdict(list)
    for r0,c0,r1,c1 in objs: bycol[c0].append((r0,c0,r1,c1))
    best=None
    for c,lst in bycol.items():
        lst.sort()
        for a,b in zip(lst,lst[1:]):
            gap=b[0]-a[2]
            if best is None or gap<best[0]: best=(gap,b)
    r0,c0,r1,c1=best[1]
    return [row[c0:c1+1] for row in g[r0:r1+1]]
